   224              }
   225              for(j = 0; j < u4_num_st_foll; j++)
   226              {
   227                  ASSERT(ai4_poc_st_foll[j] != ai4_poc_lt_curr[i]);
   228              }
   229              for(j = 0; j < u4_num_lt_curr; j++)
